'use strict';
const C=WordJournal;
const KEY='read-and-keep-demo-v1';
const $=(s,scope=document)=>scope.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shapes={book:'<path d="M3 5c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2z"/><path d="M12 7v15"/>',logo:'<path d="M3 8c4-1 6 0 9 2 3-2 5-3 9-2v12c-4-1-6 0-9 2-3-2-5-3-9-2z"/><path d="M12 10v12M12 5c1-4 4-4 7-4-1 4-3 5-7 4z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>',repeat:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18m-13 5h2m4 0h2"/>',star:'<path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.3-5.7-3-5.7 3 1.1-6.3-4.6-4.5 6.4-.9z"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',leaf:'<path d="M5 21C4 11 6 3 20 3c0 13-6 17-15 14M5 21 16 9"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--page)"/><circle cx="16" cy="17" r="3" fill="var(--page)"/>',edit:'<path d="m16 3 5 5L9 20l-6 1 1-6zM13 6l5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',note:'<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',undo:'<path d="M3 9h10a7 7 0 0 1 0 14M3 9l5-5M3 9l5 5"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||shapes.book}</svg>`;}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
let state,storageOK=true;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):null;if(state&&(!Array.isArray(state.entries)||state.entries.some(e=>typeof e.word!=='string'||typeof e.due!=='string')))throw new Error('Invalid data');}catch(e){storageOK=false;state=null;}
if(!state)state={entries:C.seed(),settings:{interval:3,batch:5},lastEntry:null};
state.settings={interval:3,batch:5,...state.settings};
initializeReader();
let route='today',filter='all',groupBy='date',query='',sourceFilter='',session=null,toastTimer;
let draft={mode:'batch',source:'',batch:'',paragraph:'',selected:{}};
let dialogState=null;
let persistedState=JSON.parse(JSON.stringify(state));
function persist(){try{if(window.CloudSession)window.CloudSession.save(state);else localStorage.setItem(KEY,JSON.stringify(state));persistedState=JSON.parse(JSON.stringify(state));storageOK=true;return true;}catch(e){state=JSON.parse(JSON.stringify(persistedState));storageOK=false;toast('暂时无法保存：'+(e.message||'请导出备份以免丢失'));return false;}}
if(storageOK)persist();
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function today(){return C.dateKey();}
function shortDate(key){const p=key.split('-');return `${Number(p[1])} 月 ${Number(p[2])} 日`;}
function dateLabel(key){return key===today()?'今天':key===C.addDays(today(),-1)?'昨天':shortDate(key);}
function countWords(){return new Set(state.entries.map(e=>C.normalize(e.word))).size;}
function sourceGroups(){const map=new Map();state.entries.slice().sort((a,b)=>b.created.localeCompare(a.created)).forEach(e=>{if(!map.has(e.source))map.set(e.source,{name:e.source,date:e.created,items:[]});map.get(e.source).items.push(e);});return [...map.values()];}
function sentenceHTML(e){if(!e.sentence)return '<span class="muted">还没有原句，可以稍后补充。</span>';const escapedWord=e.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp('('+escapedWord+')','gi');return e.sentence.split(re).map((s,i)=>i%2?`<mark>${esc(s)}</mark>`:esc(s)).join('');}
function navHTML(){return [['today','sun','今天'],['read','note','文章选词'],['library','book','生词本'],['review','repeat','回顾']].map(([id,i,label])=>`<a href="#${id}" class="nav-btn ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');}
function footer(){return `<footer class="page-footer"><span class="english">A little reading. A little remembering.</span><span>示例语料为自拟 · <span data-sync-caption>${window.CloudSession?esc(window.CloudSession.caption()):storageOK?'内容保存在此浏览器':'当前浏览器无法保存'}</span> <button class="text-link" data-action="about">关于 Demo</button></span></footer>`;}
function intro(kicker,title,subtitle,action=''){return `<div class="page-intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${action||`<div class="date-label">${icon('calendar')}${shortDate(today())}，星期${'日一二三四五六'[new Date().getDay()]}</div>`}</div>`;}
function wordCard(e){const managing=route==='library'&&bulkMode;const seen=state.entries.filter(x=>C.normalize(x.word)===C.normalize(e.word)).length;return `<article class="word-card ${managing&&bulkSelected.has(e.id)?'bulk-selected':''}" data-entry="${esc(e.id)}"><div class="word-top">${managing?`<label class="bulk-word-choice"><input type="checkbox" data-bulk-entry="${esc(e.id)}" aria-label="选择 ${esc(e.word)}，${esc(e.source)}，${shortDate(e.created)}" ${bulkSelected.has(e.id)?'checked':''}><span class="word">${esc(e.word)}</span></label>`:`<button class="word-link" data-action="detail" data-id="${esc(e.id)}" aria-label="查看 ${esc(e.word)}"><span class="word">${esc(e.word)}</span></button><button class="icon-btn ${e.star?'starred':''}" data-action="star" data-id="${esc(e.id)}" aria-label="${e.star?'取消收藏':'收藏'} ${esc(e.word)}" aria-pressed="${e.star}">${icon('star')}</button>`}</div>${e.phonetic?`<div class="phonetic">${esc(e.phonetic)}</div>`:''}<div class="meaning">${esc(e.meaning)||'<span class="muted">释义待补充</span>'}</div><p class="sentence">${sentenceHTML(e)}</p><div class="card-footer"><span class="source">${icon('book')}<span>${esc(e.source)}</span></span>${seen>1?`<span class="seen-tag">遇见 ${seen} 次</span>`:e.level==='familiar'?'<span class="seen-tag">已熟悉</span>':''}</div></article>`;}
function weekHTML(){const weekday=new Date().getDay()||7;const start=C.addDays(today(),1-weekday);return Array.from({length:7},(_,i)=>{const key=C.addDays(start,i);const done=state.entries.some(e=>e.created===key);return `<div class="day-cell"><div class="day-circle ${key===today()?'current':done?'done':''}">${done?icon('check'):'一二三四五六日'[i]}</div><span>${Number(key.slice(-2))}</span></div>`;}).join('');}
function home(){const added=state.entries.filter(e=>e.created===today());const due=C.dueEntries(state.entries);const groups=sourceGroups();const weekStart=C.addDays(today(),-6);const weekSources=new Set(state.entries.filter(e=>e.created>=weekStart).map(e=>e.source)).size;const last=state.entries.find(e=>e.id===state.lastEntry);return `${intro('YOUR READING JOURNAL','今天，也读懂一点。','把陌生的词，留在熟悉的语境里。')}<section class="overview" aria-label="阅读概览"><div class="review-banner"><div class="banner-copy"><div class="banner-kicker">${icon('leaf')}给记忆一点时间</div><h2>${due.length?'上次遇见的词，<br>今天再见一面。':'读过的每一页，<br>都在慢慢留下来。'}</h2><p>${due.length?`${due.length} 条阅读记录，等你重新遇见`:'今天的回顾已经完成，随时可以再翻翻'}</p><button class="btn primary" data-action="start-review">${due.length?'开始翻阅':'自由翻阅'} ${icon('arrow')}</button></div><div class="book-art" aria-hidden="true"><div class="art-sheet back"></div><div class="art-sheet art-front"><div class="art-small">WORDS TO KEEP</div><div class="art-word">sustain</div><div class="art-meaning">维持 · 让美好持续</div><div class="art-lines"></div></div><div class="art-leaf">${icon('leaf')}</div></div></div><div class="summary-card"><div class="summary-title">一点一滴，都算数 ${icon('spark')}</div><div class="stats"><div class="stat"><strong>${countWords()}</strong><span>积累的词语</span></div><div class="stat"><strong>${weekSources}</strong><span>近 7 天阅读</span></div></div><div class="week">${weekHTML()}</div></div></section><div class="reader-home-entry">${icon('note')}<span><strong>从一篇文章，开始今天的拾词</strong><small>上传 PDF / TXT，点选生词，自动保存与翻译。</small></span><a class="btn soft" href="#read">文章选词 ${icon('arrow')}</a></div><div class="content-layout"><section><div class="section-heading"><h2>${added.length?'今天的拾词':'最近的拾词'}<span class="count">${added.length||state.entries.length}</span></h2><a class="text-link" href="#library">查看全部 ${icon('arrow')}</a></div>${state.entries.length?`<div class="entry-grid">${(added.length?added:state.entries).slice(0,6).map(wordCard).join('')}</div>`:empty('从一个词开始','记录今天阅读中遇见的第一个生词。','记录生词','add')}${last?`<button class="text-link" data-action="detail" data-id="${esc(last.id)}">${icon('clock')}继续查看：${esc(last.word)}</button>`:''}</section><aside class="trail"><div class="section-heading"><h2>阅读足迹</h2><span class="muted small">${groups.length} 篇</span></div><div class="trail-list">${groups.slice(0,3).map((g,i)=>`<button class="trail-item" data-action="source" data-source="${esc(g.name)}"><span class="trail-num">0${i+1}</span><span class="trail-text"><strong>${esc(g.name)}</strong><span>${dateLabel(g.date)} · ${g.items.length} 条记录</span></span>${icon('chevron')}</button>`).join('')||'<p class="small muted">你的阅读足迹会出现在这里。</p>'}</div><div class="quiet-note">${icon('leaf')}<p>Every word has<br>a story.<br>Keep yours.</p><span>留下原句，也留下理解它的瞬间。</span></div></aside></div>${footer()}`;}
function empty(title,description,label,action){return `<div class="empty">${icon('book')}<h2>${title}</h2><p>${description}</p>${label?`<button class="btn primary" data-action="${action}">${label}${icon('arrow')}</button>`:''}</div>`;}
function filteredEntries(){const q=query.trim().toLowerCase();return state.entries.filter(e=>(filter==='all'||filter==='starred'&&e.star||filter==='familiar'&&e.level==='familiar')&&(!sourceFilter||e.source===sourceFilter)&&(!q||[e.word,e.meaning,e.source,e.sentence,e.note].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.created.localeCompare(a.created));}
function libraryResults(){const entries=filteredEntries(),controls=bulkMode?bulkControls(entries):'';if(!entries.length)return controls+empty('还没有找到这个词','换个关键词试试，或者留下一个新的阅读记录。','清除筛选','clear-filters');const groups=new Map();entries.forEach(e=>{const key=groupBy==='date'?e.created:e.source;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);});return controls+`<div class="small muted" role="status">找到 ${entries.length} 条阅读记录</div>`+[...groups].map(([key,items])=>`<section><h2 class="group-title">${groupBy==='date'?dateLabel(key)+' · '+shortDate(key):esc(key)}<span>${items.length} 条记录</span></h2><div class="library-grid">${items.map(wordCard).join('')}</div></section>`).join('');}
function library(){return `${intro('YOUR WORD COLLECTION','每一个词，都有来处。',`${countWords()} 个词语，${state.entries.length} 次遇见。慢慢积累，随时翻阅。`,`<div class="library-intro-actions"><button class="btn ${bulkMode?'soft':''}" data-bulk="toggle" aria-pressed="${bulkMode}">${icon(bulkMode?'check':'settings')}${bulkMode?'完成管理':'批量管理'}</button><button class="btn" data-action="export">${icon('download')}导出备份</button></div>`)}<div class="library-toolbar"><label class="search-wrap">${icon('search')}<input id="search" type="search" aria-label="搜索单词、释义或原句" placeholder="搜索单词、释义或原句…" value="${esc(query)}"></label><select id="source-filter" aria-label="筛选阅读文章"><option value="">全部阅读文章</option>${librarySourceOptions().map(g=>`<option ${g.name===sourceFilter?'selected':''} value="${esc(g.name)}">${esc(g.name)}</option>`).join('')}</select></div><div class="filter-row"><div class="pills">${[['all','全部记录'],['starred','想再看看'],['familiar','已熟悉']].map(([id,label])=>`<button class="pill ${filter===id?'active':''}" data-action="filter" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div class="sort-toggle"><button data-action="group" data-group="date" class="${groupBy==='date'?'active':''}" aria-pressed="${groupBy==='date'}">按日期</button><button data-action="group" data-group="source" class="${groupBy==='source'?'active':''}" aria-pressed="${groupBy==='source'}">按文章</button></div></div><div id="library-results">${libraryResults()}</div>${footer()}`;}
function beginSession(free=false){const list=free?state.entries:C.dueEntries(state.entries);session={ids:list.slice(0,state.settings.batch).map(e=>e.id),index:0,history:[],free};}
function review(){if(!session)beginSession();const due=C.dueEntries(state.entries);const header=intro('A LITTLE REVISIT','再见面，多一分熟悉。','带着原句读一读，按自己的节奏来。',`<button class="btn" data-action="settings">${icon('settings')}回顾节奏</button>`);if(!session.ids.length)return `${header}<div class="review-wrap">${empty('今天的回顾已经完成','新记录会在明天出现。也可以随时翻阅整个生词本。',state.entries.length?'自由翻阅':'记录生词',state.entries.length?'free-review':'add')}</div>${footer()}`;if(session.index>=session.ids.length)return `${header}<div class="review-wrap"><div class="session-finish">${icon('leaf')}<div class="eyebrow">A LITTLE MORE FAMILIAR</div><h2>这一页，读进心里了。</h2><p>你刚刚回看了 ${session.ids.length} 条记录。<br>下一次见面，已经为你安排好。</p>${due.length?`<button class="btn primary" data-action="next-session">再翻 ${Math.min(due.length,state.settings.batch)} 条 ${icon('arrow')}</button>`:''}<a href="#library" class="btn ${due.length?'':'primary'}">去生词本看看 ${icon('book')}</a></div>${session.history.length?'<button class="session-undo" data-action="undo-review">撤销上一条回顾</button>':''}</div>${footer()}`;const e=state.entries.find(e=>e.id===session.ids[session.index]);if(!e){session.index++;return review();}return `${header}<div class="review-wrap"><div class="review-topline"><span>${session.free?'自由翻阅':'今日回顾'} · ${session.index+1} / ${session.ids.length}</span>${session.history.length?'<button class="session-undo" data-action="undo-review">撤销上一条</button>':'<span>每次一点点，就很好</span>'}</div><div class="progress-track" role="progressbar" aria-label="本次回顾进度" aria-valuemin="0" aria-valuemax="${session.ids.length}" aria-valuenow="${session.index}"><div class="progress-fill" style="width:${session.index/session.ids.length*100}%"></div></div><article class="review-card"><div class="word-top"><span class="word">${esc(e.word)}</span><button class="icon-btn ${e.star?'starred':''}" data-action="star" data-id="${e.id}" aria-label="${e.star?'取消收藏':'收藏'} ${esc(e.word)}" aria-pressed="${e.star}">${icon('star')}</button></div>${e.phonetic?`<p class="phonetic">${esc(e.phonetic)}</p>`:''}<p class="meaning">${esc(e.meaning)||'释义待补充'}</p><div class="review-context"><div class="context-label">BACK TO THE CONTEXT · 回到原文</div><p class="sentence">${sentenceHTML(e)}</p><div class="source">${icon('book')}<span>${esc(e.source)} · ${dateLabel(e.created)}记录</span></div></div>${e.note?`<p class="note-line">${icon('note')}${esc(e.note)}</p>`:''}<button class="text-link" data-action="detail" data-id="${e.id}">查看这次遇见的完整记录 ${icon('arrow')}</button></article><div class="review-actions"><button class="btn" data-action="rate" data-choice="again">稍后再看<small>明天再见</small></button><button class="btn primary" data-action="rate" data-choice="read">已翻阅<small>${state.settings.interval} 天后再见</small></button><button class="btn" data-action="rate" data-choice="less">减少出现<small>7 天后再见</small></button></div><p class="review-hint">不需要答题，也没有倒计时。读懂此刻的语境就好。</p></div>${footer()}`;}
function render(){route=['today','read','library','review'].includes(location.hash.slice(1))?location.hash.slice(1):'today';document.body.dataset.page=route;$('#desktop-nav').innerHTML=navHTML();$('#mobile-nav').innerHTML=navHTML();$('#main').innerHTML=route==='today'?home():route==='read'?readerPage():route==='library'?library():review();$('#brand-icon').innerHTML=icon('logo');hydrateIcons();readerAfterRender();bulkAfterRender();window.CloudSession?.refreshStatus();}
function navigate(next){if(location.hash==='#'+next)render();else location.hash=next;}
function showDialog(title,body){const d=$('#modal');$('#modal-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();}
function closeDialog(){ $('#modal').close();dialogState=null;}
function addDialog(){dialogState='add';showDialog('留住今天遇见的词',`<p class="dialog-subtitle">先记下来，释义和原句可以慢慢补充。</p><form id="add-form"><div class="form-row"><label for="entry-source">阅读文章 <small>选填</small></label><input id="entry-source" name="source" maxlength="150" placeholder="例如：The future of our cities" value="${esc(draft.source)}"></div><div class="segmented" aria-label="录入方式"><button type="button" data-action="add-mode" data-mode="batch" class="${draft.mode==='batch'?'active':''}" aria-pressed="${draft.mode==='batch'}">批量记词</button><button type="button" data-action="add-mode" data-mode="paragraph" class="${draft.mode==='paragraph'?'active':''}" aria-pressed="${draft.mode==='paragraph'}">从原句选词</button></div>${draft.mode==='batch'?`<div class="form-row"><label for="batch-input">生词清单</label><textarea id="batch-input" name="batch" rows="5" maxlength="20000" placeholder="每行一个词，也可以带上释义和原句：&#10;sustain | 维持；支撑 | The region cannot sustain its current population.&#10;urban sprawl | 城市蔓延">${esc(draft.batch)}</textarea><p class="field-hint">支持单词和短语。用 | 分隔词语、释义、原句。</p></div>`:`<div class="form-row"><label for="paragraph-input">粘贴阅读原文</label><textarea id="paragraph-input" name="paragraph" rows="4" maxlength="10000" placeholder="粘贴 PDF 或网页中的一段英文，然后点选要留下的词。">${esc(draft.paragraph)}</textarea></div><div id="token-area"></div><div id="selected-words"></div>`}<button type="button" class="text-link" data-action="fill-example">${icon('spark')}填入一段示例试试</button><p class="error" id="add-error" role="alert"></p><div class="form-footer"><span class="muted" id="draft-count">记录日期：${shortDate(today())}</span><button type="submit" class="btn primary" id="save-entries">保存生词 ${icon('arrow')}</button></div></form>`);if(draft.mode==='paragraph')renderTokens();updateDraftCount();}
function captureDraft(){if(dialogState!=='add')return;draft.source=$('#entry-source')?.value||'';if(draft.mode==='batch')draft.batch=$('#batch-input')?.value||'';else draft.paragraph=$('#paragraph-input')?.value||'';}
function selectedRows(){return Object.values(draft.selected).map(e=>({...e,sentence:(draft.paragraph.match(/[^.!?]+[.!?]?/g)||[draft.paragraph]).find(s=>new RegExp('\\b'+e.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(s))?.trim()||draft.paragraph}));}
function updateDraftCount(){const rows=draft.mode==='batch'?C.parseBatch(draft.batch):selectedRows();const c=$('#draft-count');if(c)c.textContent=rows.length?`已选 ${rows.length} 条 · ${shortDate(today())}`:`记录日期：${shortDate(today())}`;const btn=$('#save-entries');if(btn)btn.innerHTML=`保存${rows.length?' '+rows.length+' 个':''}生词 ${icon('arrow')}`;}
function renderTokens(){const area=$('#token-area');if(!area)return;const parts=draft.paragraph.split(/([a-zA-Z]+(?:['’-][a-zA-Z]+)*)/g);area.innerHTML=draft.paragraph?`<p class="field-hint">点选下面的词语，再点一次取消。</p><div class="token-area">${parts.map((part,i)=>i%2?`<button type="button" class="token ${draft.selected[C.normalize(part)]?'selected':''}" data-action="token" data-word="${esc(part)}" aria-pressed="${Boolean(draft.selected[C.normalize(part)])}">${esc(part)}</button>`:esc(part)).join('')}</div>`:'';$('#selected-words').innerHTML=Object.entries(draft.selected).map(([key,e])=>`<div class="selected-word"><strong>${esc(e.word)}</strong><input aria-label="${esc(e.word)} 的释义" placeholder="补充本文释义" data-meaning="${esc(key)}" value="${esc(e.meaning)}"><button type="button" class="icon-btn" data-action="token" data-word="${esc(e.word)}" aria-label="取消选择 ${esc(e.word)}">${icon('close')}</button></div>`).join('');updateDraftCount();}
function detail(id){const e=state.entries.find(e=>e.id===id);if(!e)return;dialogState='detail';$('#modal').dataset.entry=id;state.lastEntry=e.id;persist();const related=state.entries.filter(x=>x.id!==id&&C.normalize(x.word)===C.normalize(e.word));showDialog('一次阅读，一次遇见',`<div class="detail-hero"><div class="word-top"><h3 class="word">${esc(e.word)}</h3><button class="icon-btn ${e.star?'starred':''}" data-action="detail-star" data-id="${e.id}" aria-label="${e.star?'取消收藏':'收藏'} ${esc(e.word)}" aria-pressed="${e.star}">${icon('star')}</button></div><p class="phonetic">${esc(e.phonetic)}</p><p class="meaning">${esc(e.meaning)||'释义待补充'}</p></div><div class="detail-context"><div class="context-label">原文中的它</div><p class="sentence">${sentenceHTML(e)}</p></div><p class="detail-meta">${esc(e.source)} · ${shortDate(e.created)}记录<br>已回看 ${e.reviews} 次 · 下次回看 ${shortDate(e.due)}${e.sample?'<br><span class="sample-note">演示内容 · 自拟语料</span>':''}</p>${readerDetailExtra(e)}${e.note?`<div class="detail-note">我的笔记：${esc(e.note)}</div>`:''}${related.length?`<div class="section-heading"><h3 class="small">也在这些地方遇见过</h3></div>${related.map(x=>`<div class="encounter"><span class="muted small">${esc(x.source)} · ${shortDate(x.created)}</span><p class="sentence">${sentenceHTML(x)}</p></div>`).join('')}`:''}<div class="detail-actions"><button class="btn ghost danger" data-action="delete-prompt" data-id="${id}">${icon('trash')}删除记录</button><button class="btn" data-action="edit" data-id="${id}">${icon('edit')}编辑记录</button></div>`);}
function edit(id){const e=state.entries.find(x=>x.id===id);if(!e)return;dialogState='edit';showDialog('编辑这次遇见',`<form id="edit-form" data-id="${id}" data-initial-meaning="${esc(e.meaning)}"><div class="form-row"><label for="edit-word">单词或短语</label><input id="edit-word" name="word" value="${esc(e.word)}" required maxlength="150"></div><div class="form-row"><label for="edit-meaning">本文释义</label><input id="edit-meaning" name="meaning" value="${esc(e.meaning)}" maxlength="500"></div><div class="form-row"><label for="edit-sentence">原句</label><textarea id="edit-sentence" name="sentence" rows="3" maxlength="10000">${esc(e.sentence)}</textarea></div><div class="form-row"><label for="edit-source">文章来源</label><input id="edit-source" name="source" value="${esc(e.source)}" maxlength="150"></div><div class="form-row"><label for="edit-note">我的笔记</label><textarea id="edit-note" name="note" rows="2" maxlength="3000">${esc(e.note)}</textarea></div><p id="edit-error" class="error" role="alert"></p><div class="form-footer"><span class="muted">保存后请留意页面顶部的同步状态</span><button type="submit" class="btn primary">保存修改 ${icon('check')}</button></div></form>`);}
function settings(){dialogState='settings';showDialog('按你的节奏回顾',`<p class="dialog-subtitle">少量、经常。找到让自己舒服的节奏。</p><form id="settings-form"><div class="form-row"><label>每次翻阅多少条</label>${[5,10,15].map(n=>`<label class="settings-choice"><input type="radio" name="batch" value="${n}" ${state.settings.batch===n?'checked':''}>${n} 条${n===5?' · 从一点点开始':''}</label>`).join('')}</div><div class="form-row"><label for="interval">点击“已翻阅”后，下次何时出现</label><select id="interval" name="interval">${[1,3,7].map(n=>`<option value="${n}" ${n===state.settings.interval?'selected':''}>${n} 天后</option>`).join('')}</select></div><div class="info-box">“稍后再看”固定为明天，“减少出现”固定为 7 天后。新记录在次日加入回顾。调整条数从下一组开始生效。</div><div class="form-footer"><span class="muted">Demo 使用应用内提示</span><button type="submit" class="btn primary">保存设置 ${icon('check')}</button></div></form>`);}
function about(){dialogState='about';showDialog('关于拾词',`<div class="about-mark">${icon('logo')}</div><p style="font-size:20px;font-weight:550">把阅读中遇见的词，好好留下。</p><p class="dialog-subtitle" style="margin-top:9px">Read a little. Keep a little.</p><div class="info-box">这是可以实际操作的首版 Demo。访客记录保存在当前浏览器；登录后，文章、生词和回顾设置会保存到个人云端空间。请留意同步状态，未同步内容仍只在本机。支持导入文字版 PDF、TXT 和粘贴文章，点选词语后自动收录。词性、词形和例句由 FreeDictionaryAPI 提供。所选词发送至词典；所选词、原句与词典释义、例句发送至 MyMemory 翻译。结果为可编辑的参考；翻译与词典服务不接收整篇文章。登录后的文章全文会保存到 Supabase。同一账号可在手机和电脑读取已同步记录。专用 AI 语境模型和系统通知尚未接入。</div><p class="small muted">内置文章标题、原句和释义用于演示，语料为自拟。你可以直接添加自己的内容；保存到不同浏览器或清除网站数据时，请先导出备份。</p><div class="form-footer"><span class="muted">拾词 · 初版交互演示</span><button class="btn" data-action="export">${icon('download')}导出备份</button></div>`);}
function exportData(){const text=JSON.stringify({app:'拾词 Read & Keep',version:1,exportedAt:new Date().toISOString(),...state},null,2);const blob=new Blob([text],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`拾词备份-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出');}
document.addEventListener('click',ev=>{
  const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
  if(a==='add'){addDialog();return;}
  if(a==='close'){captureDraft();captureArticleDraft();if(dialogState==='import'){importTicket++;articleDraft.busy=false;}closeDialog();return;}
  if(a==='about'){about();return;}
  if(a==='detail'){detail(id);return;}
  if(a==='edit'){edit(id);return;}
  if(a==='export'){exportData();return;}
  if(a==='settings'){settings();return;}
  if(a==='star'||a==='detail-star'){const e=state.entries.find(x=>x.id===id);if(!e)return;e.star=!e.star;const ok=persist();render();if(a==='detail-star')detail(id);if(ok)toast(e.star?'已放入“想再看看”':'已取消收藏');return;}
  if(a==='source'){sourceFilter=el.dataset.source;filter='all';query='';navigate('library');return;}
  if(a==='filter'){filter=el.dataset.filter;render();return;}
  if(a==='group'){groupBy=el.dataset.group;render();return;}
  if(a==='clear-filters'){query='';sourceFilter='';filter='all';render();return;}
  if(a==='start-review'||a==='free-review'||a==='next-session'){beginSession(a==='free-review'||a==='start-review'&&!C.dueEntries(state.entries).length);navigate('review');return;}
  if(a==='rate'){if(!session||session.index>=session.ids.length)return;const entry=state.entries.find(e=>e.id===session.ids[session.index]);session.history.push({...entry});state.entries=state.entries.map(e=>e.id===entry.id?C.reviewed(e,el.dataset.choice,state.settings.interval):e);state.lastEntry=entry.id;session.index++;persist();render();window.scrollTo({top:0,behavior:'instant'});return;}
  if(a==='undo-review'){const previous=session?.history.pop();if(!previous)return;state.entries=state.entries.map(e=>e.id===previous.id?previous:e);session.index--;persist();render();toast('已撤销，可以重新选择');return;}
  if(a==='add-mode'){captureDraft();draft.mode=el.dataset.mode;addDialog();return;}
  if(a==='fill-example'){captureDraft();draft.source='Life beneath the ocean';if(draft.mode==='batch')draft.batch='adapt | 适应 | Marine organisms adapt to changes in their environment.\nscarce | 稀少的 | Food can be scarce in the deep ocean.\nin response to | 作为对……的反应 | Some species move in response to rising temperatures.';else{draft.paragraph='Marine organisms adapt to changes in their environment. Food can be scarce in the deep ocean.';draft.selected={};}addDialog();return;}
  if(a==='token'){const word=el.dataset.word,key=C.normalize(word);if(draft.selected[key])delete draft.selected[key];else draft.selected[key]={word,meaning:state.entries.find(e=>C.normalize(e.word)===key)?.meaning||''};renderTokens();return;}
  if(a==='delete-prompt'){dialogState='delete';const e=state.entries.find(e=>e.id===id);showDialog('删除这条阅读记录？',`<p class="dialog-subtitle">将移除 ${esc(e.word)} 在「${esc(e.source)}」中的这次遇见。其他原句中的同一个词会保留。</p><button class="btn danger" data-action="delete" data-id="${id}">${icon('trash')}确认删除</button>`);return;}
  if(a==='delete'){const count=deleteRecordIds([id]);if(count===null)return;closeDialog();render();if(count)toast('已删除这次阅读记录');return;}
});
document.addEventListener('input',ev=>{
  if(ev.target.id==='search'){query=ev.target.value;$('#library-results').innerHTML=libraryResults();bulkSync();}
  if(ev.target.id==='batch-input'){draft.batch=ev.target.value;updateDraftCount();}
  if(ev.target.id==='entry-source')draft.source=ev.target.value;
  if(ev.target.id==='paragraph-input'){draft.paragraph=ev.target.value;for(const key of Object.keys(draft.selected)){if(!draft.paragraph.toLowerCase().includes(key))delete draft.selected[key];}renderTokens();}
  if(ev.target.dataset.meaning){const key=ev.target.dataset.meaning;if(draft.selected[key])draft.selected[key].meaning=ev.target.value;}
});
document.addEventListener('change',ev=>{if(ev.target.id==='source-filter'){sourceFilter=ev.target.value;$('#library-results').innerHTML=libraryResults();bulkSync();}});
document.addEventListener('submit',ev=>{
  if(ev.target.id==='add-form'){ev.preventDefault();captureDraft();const rows=draft.mode==='batch'?C.parseBatch(draft.batch):selectedRows();if(!rows.length){$('#add-error').textContent=draft.mode==='batch'?'请至少输入一个单词或短语。':'请在原文中点选至少一个词。';return;}if(rows.some(r=>r.word.length>150)){$('#add-error').textContent='单个词语太长了，请检查是否误把整段原文放进了词语栏。';return;}const result=C.addEntries(state.entries,rows,draft.source.trim()||'未命名阅读');if(!result.added){$('#add-error').textContent='这些词今天已经在同一篇文章、同一个原句中记录过了。';return;}state.entries=result.entries;const ok=persist();if(!ok){$('#add-error').textContent='尚未保存，请保留输入并重试。';return;}draft={mode:'batch',source:'',batch:'',paragraph:'',selected:{}};closeDialog();render();if(ok)toast(`已留下 ${result.added} 个生词，明天会出现在回顾里`);}
  if(ev.target.id==='edit-form'){ev.preventDefault();const form=new FormData(ev.target),id=ev.target.dataset.id;const word=form.get('word').trim();if(!word){$('#edit-error').textContent='请输入单词或短语。';return;}state.entries=state.entries.map(e=>{if(e.id!==id)return e;const meaning=form.get('meaning').trim(),sentence=form.get('sentence').trim();const manual=meaning!==(ev.target.dataset.initialMeaning||''),contextChanged=word!==e.word||sentence!==e.sentence;if(manual||contextChanged)cancelEntryTranslation(id);return {...e,...(contextChanged?{lexicon:null}:{}),word,sentence,meaning:manual?meaning:contextChanged?'':e.meaning,source:form.get('source').trim()||'未命名阅读',note:form.get('note').trim(),...(e.articleId&&(manual||contextChanged)?{meaningEdited:manual,translationStatus:manual?'manual':'idle',translationVersion:(e.translationVersion||0)+1,translationError:'',...(contextChanged?{sentenceTranslation:'',lexicon:null,locationStale:Boolean(e.articleId)}:{})}:{})};});const ok=persist();if(!ok){$('#edit-error').textContent='尚未保存，请保留修改并重试。';return;}render();detail(id);if(ok)toast('修改已保存');}
  if(ev.target.id==='settings-form'){ev.preventDefault();const f=new FormData(ev.target);state.settings={...state.settings,batch:Number(f.get('batch')),interval:Number(f.get('interval'))};const ok=persist();if(!ok)return;closeDialog();render();toast('回顾节奏已更新');}
});
$('#modal').addEventListener('cancel',()=>{captureDraft();captureArticleDraft();if(dialogState==='import'){importTicket++;articleDraft.busy=false;}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',ev=>{if(ev.key===KEY&&ev.newValue&&(!window.CloudSession||window.CloudSession.ownsGuest())){try{const updated=JSON.parse(ev.newValue);if(Array.isArray(updated.entries)){state=updated;persistedState=JSON.parse(JSON.stringify(updated));render();}}catch{}}});
render();
if(!storageOK)setTimeout(()=>toast('浏览器存储不可用，请及时导出备份'),500);
